    item.innerHTML = '<button class="nav-site-search-btn" type="button" data-site-search-open aria-label="Search Athanas Inspires"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg><span>Search</span></button>';
    const support = nav.querySelector(".nav-dropdown-support");
    if (support?.parentElement === nav) nav.insertBefore(item, support);
